PLM06 = mk(
    "LM06",
    "\u5bf9\u94fe\u8868\u8fdb\u884c\u63d2\u5165\u6392\u5e8f",
    "LeetCode 147",
    "medium",
    "\u94fe\u8868",
    "\u7ed9\u5b9a\u5355\u4e2a\u94fe\u8868\u7684\u5934\u00a0head\u00a0\uff0c\u4f7f\u7528 \u63d2\u5165\u6392\u5e8f \u5bf9\u94fe\u8868\u8fdb\u884c\u6392\u5e8f\uff0c\u5e76\u8fd4\u56de\u00a0\u6392\u5e8f\u540e\u94fe\u8868\u7684\u5934\u00a0\u3002\n\n\u63d2\u5165\u6392\u5e8f\u00a0\u7b97\u6cd5\u7684\u6b65\u9aa4:\n\n\t\u63d2\u5165\u6392\u5e8f\u662f\u8fed\u4ee3\u7684\uff0c\u6bcf\u6b21\u53ea\u79fb\u52a8\u4e00\u4e2a\u5143\u7d20\uff0c\u76f4\u5230\u6240\u6709\u5143\u7d20\u53ef\u4ee5\u5f62\u6210\u4e00\u4e2a\u6709\u5e8f\u7684\u8f93\u51fa\u5217\u8868\u3002\n\n\t\u6bcf\u6b21\u8fed\u4ee3\u4e2d\uff0c\u63d2\u5165\u6392\u5e8f\u53ea\u4ece\u8f93\u5165\u6570\u636e\u4e2d\u79fb\u9664\u4e00\u4e2a\u5f85\u6392\u5e8f\u7684\u5143\u7d20\uff0c\u627e\u5230\u5b83\u5728\u5e8f\u5217\u4e2d\u9002\u5f53\u7684\u4f4d\u7f6e\uff0c\u5e76\u5c06\u5176\u63d2\u5165\u3002\n\n\t\u91cd\u590d\u76f4\u5230\u6240\u6709\u8f93\u5165\u6570\u636e\u63d2\u5165\u5b8c\u4e3a\u6b62\u3002\n\n\u4e0b\u9762\u662f\u63d2\u5165\u6392\u5e8f\u7b97\u6cd5\u7684\u4e00\u4e2a\u56fe\u5f62\u793a\u4f8b\u3002\u90e8\u5206\u6392\u5e8f\u7684\u5217\u8868(\u9ed1\u8272)\u6700\u521d\u53ea\u5305\u542b\u5217\u8868\u4e2d\u7684\u7b2c\u4e00\u4e2a\u5143\u7d20\u3002\u6bcf\u6b21\u8fed\u4ee3\u65f6\uff0c\u4ece\u8f93\u5165\u6570\u636e\u4e2d\u5220\u9664\u4e00\u4e2a\u5143\u7d20(\u7ea2\u8272)\uff0c\u5e76\u5c31\u5730\u63d2\u5165\u5df2\u6392\u5e8f\u7684\u5217\u8868\u4e2d\u3002\n\n\u5bf9\u94fe\u8868\u8fdb\u884c\u63d2\u5165\u6392\u5e8f\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165: head = [4,2,1,3]\n\u8f93\u51fa: [1,2,3,4]\n```\n\n\u793a\u4f8b\u00a02\uff1a\n\n```\n\u8f93\u5165: head = [-1,5,3,4,0]\n\u8f93\u51fa: [-1,0,3,4,5]\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t\u5217\u8868\u4e2d\u7684\u8282\u70b9\u6570\u5728\u00a0[1, 5000]\u8303\u56f4\u5185\n\n\t-5000 <= Node.val <= 5000",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1ahead\u3002",
    "\u8f93\u51fa ListNode \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef _list_build(vals):\n    head = cur = ListNode()\n    for v in vals:\n        cur.next = ListNode(v)\n        cur = cur.next\n    return head.next\n\ndef _list_show(head):\n    out = []\n    while head:\n        out.append(head.val)\n        head = head.next\n    return out\n\ndef _list_array_build(arr):\n    return [_list_build(x) for x in arr]\n\ndef _list_array_show(arr):\n    return [_list_show(x) for x in arr]\n\nclass Solution:\n    def insertionSortList(self, head: ListNode) -> ListNode:\n        if not head:\n            return head\n        \n        dummyHead = ListNode(0)\n        dummyHead.next = head\n        lastSorted = head\n        curr = head.next\n\n        while curr:\n            if lastSorted.val <= curr.val:\n                lastSorted = lastSorted.next\n            else:\n                prev = dummyHead\n                while prev.next.val <= curr.val:\n                    prev = prev.next\n                lastSorted.next = curr.next\n                curr.next = prev.next\n                prev.next = curr\n            curr = lastSorted.next\n        \n        return dummyHead.next\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n    _args[0] = _list_build(_args[0])\n    _ret = _sol.insertionSortList(_args[0])\n    _out = json.dumps(_list_show(_ret), separators=(',', ':'))\n    sys.stdout.write(_out)\n\nmain()\n",
    "token_list",
    [["[4,2,1,3]", "[1,2,3,4]"], ["[-1,5,3,4,0]", "[-1,0,3,4,5]"]],
    ["linked-list", "sorting", "\u94fe\u8868"],
    )
