    "\u4f60\u9700\u8981\u8bbe\u8ba1\u4e00\u4e2a\u5305\u542b\u9a8c\u8bc1\u7801\u7684\u9a8c\u8bc1\u7cfb\u7edf\u3002\u6bcf\u4e00\u6b21\u9a8c\u8bc1\u4e2d\uff0c\u7528\u6237\u4f1a\u6536\u5230\u4e00\u4e2a\u65b0\u7684\u9a8c\u8bc1\u7801\uff0c\u8fd9\u4e2a\u9a8c\u8bc1\u7801\u5728 currentTime\u00a0\u65f6\u523b\u4e4b\u540e timeToLive\u00a0\u79d2\u8fc7\u671f\u3002\u5982\u679c\u9a8c\u8bc1\u7801\u88ab\u66f4\u65b0\u4e86\uff0c\u90a3\u4e48\u5b83\u4f1a\u5728 currentTime\u00a0\uff08\u53ef\u80fd\u4e0e\u4e4b\u524d\u7684 currentTime\u00a0\u4e0d\u540c\uff09\u65f6\u523b\u5ef6\u957f\u00a0timeToLive\u00a0\u79d2\u3002\n\n\u8bf7\u4f60\u5b9e\u73b0\u00a0AuthenticationManager\u00a0\u7c7b\uff1a\n\n\tAuthenticationManager(int timeToLive)\u00a0\u6784\u9020\u00a0AuthenticationManager\u00a0\u5e76\u8bbe\u7f6e\u00a0timeToLive\u00a0\u53c2\u6570\u3002\n\n\tgenerate(string tokenId, int currentTime)\u00a0\u7ed9\u5b9a tokenId\u00a0\uff0c\u5728\u5f53\u524d\u65f6\u95f4\u00a0currentTime \u751f\u6210\u4e00\u4e2a\u65b0\u7684\u9a8c\u8bc1\u7801\u3002\n\n\trenew(string tokenId, int currentTime)\u00a0\u5c06\u7ed9\u5b9a tokenId\u00a0\u4e14 \u672a\u8fc7\u671f\u00a0\u7684\u9a8c\u8bc1\u7801\u5728 currentTime\u00a0\u65f6\u523b\u66f4\u65b0\u3002\u5982\u679c\u7ed9\u5b9a\u00a0tokenId\u00a0\u5bf9\u5e94\u7684\u9a8c\u8bc1\u7801\u4e0d\u5b58\u5728\u6216\u5df2\u8fc7\u671f\uff0c\u8bf7\u4f60\u5ffd\u7565\u8be5\u64cd\u4f5c\uff0c\u4e0d\u4f1a\u6709\u4efb\u4f55\u66f4\u65b0\u64cd\u4f5c\u53d1\u751f\u3002\n\n\tcountUnexpiredTokens(int currentTime)\u00a0\u8bf7\u8fd4\u56de\u5728\u7ed9\u5b9a\u00a0currentTime\u00a0\u65f6\u523b\uff0c\u672a\u8fc7\u671f\u00a0\u7684\u9a8c\u8bc1\u7801\u6570\u76ee\u3002\n\n\u5982\u679c\u4e00\u4e2a\u9a8c\u8bc1\u7801\u5728\u65f6\u523b\u00a0t\u00a0\u8fc7\u671f\uff0c\u4e14\u53e6\u4e00\u4e2a\u64cd\u4f5c\u6070\u597d\u5728\u65f6\u523b\u00a0t\u00a0\u53d1\u751f\uff08renew\u00a0\u6216\u8005\u00a0countUnexpiredTokens\u00a0\u64cd\u4f5c\uff09\uff0c\u8fc7\u671f\u4e8b\u4ef6\u00a0\u4f18\u5148\u4e8e\u00a0\u5176\u4ed6\u64cd\u4f5c\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1a\n[\"AuthenticationManager\", \"renew\", \"generate\", \"countUnexpiredTokens\", \"generate\", \"renew\", \"renew\", \"countUnexpiredTokens\"]\n[[5], [\"aaa\", 1], [\"aaa\", 2], [6], [\"bbb\", 7], [\"aaa\", 8], [\"bbb\", 10], [15]]\n\u8f93\u51fa\uff1a\n[null, null, null, 1, null, null, null, 0]\n\n\u89e3\u91ca\uff1a\nAuthenticationManager authenticationManager = new AuthenticationManager(5); // \u6784\u9020 AuthenticationManager \uff0c\u8bbe\u7f6e timeToLive = 5 \u79d2\u3002\nauthenticationManager.renew(\"aaa\", 1); // \u65f6\u523b 1 \u65f6\uff0c\u6ca1\u6709\u9a8c\u8bc1\u7801\u7684 tokenId \u4e3a \"aaa\" \uff0c\u6ca1\u6709\u9a8c\u8bc1\u7801\u88ab\u66f4\u65b0\u3002\nauthenticationManager.generate(\"aaa\", 2); // \u65f6\u523b 2 \u65f6\uff0c\u751f\u6210\u4e00\u4e2a tokenId \u4e3a \"aaa\" \u7684\u65b0\u9a8c\u8bc1\u7801\u3002\nauthenticationManager.countUnexpiredTokens(6); // \u65f6\u523b 6 \u65f6\uff0c\u53ea\u6709 tokenId \u4e3a \"aaa\" \u7684\u9a8c\u8bc1\u7801\u672a\u8fc7\u671f\uff0c\u6240\u4ee5\u8fd4\u56de 1 \u3002\nauthenticationManager.generate(\"bbb\", 7); // \u65f6\u523b 7 \u65f6\uff0c\u751f\u6210\u4e00\u4e2a tokenId \u4e3a \"bbb\" \u7684\u65b0\u9a8c\u8bc1\u7801\u3002\nauthenticationManager.renew(\"aaa\", 8); // tokenId \u4e3a \"aaa\" \u7684\u9a8c\u8bc1\u7801\u5728\u65f6\u523b 7 \u8fc7\u671f\uff0c\u4e14 8 >= 7 \uff0c\u6240\u4ee5\u65f6\u523b 8 \u7684renew \u64cd\u4f5c\u88ab\u5ffd\u7565\uff0c\u6ca1\u6709\u9a8c\u8bc1\u7801\u88ab\u66f4\u65b0\u3002\nauthenticationManager.renew(\"bbb\", 10); // tokenId \u4e3a \"bbb\" \u7684\u9a8c\u8bc1\u7801\u5728\u65f6\u523b 10 \u6ca1\u6709\u8fc7\u671f\uff0c\u6240\u4ee5 renew \u64cd\u4f5c\u4f1a\u6267\u884c\uff0c\u8be5 token \u5c06\u5728\u65f6\u523b 15 \u8fc7\u671f\u3002\nauthenticationManager.countUnexpiredTokens(15); // tokenId \u4e3a \"bbb\" \u7684\u9a8c\u8bc1\u7801\u5728\u65f6\u523b 15 \u8fc7\u671f\uff0ctokenId \u4e3a \"aaa\" \u7684\u9a8c\u8bc1\u7801\u5728\u65f6\u523b 7 \u8fc7\u671f\uff0c\u6240\u6709\u9a8c\u8bc1\u7801\u5747\u5df2\u8fc7\u671f\uff0c\u6240\u4ee5\u8fd4\u56de 0 \u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 8\n\n\t1 8\n\n\t1\n\n\ttokenId\u00a0\u53ea\u5305\u542b\u5c0f\u5199\u82f1\u6587\u5b57\u6bcd\u3002\n\n\t\u6240\u6709\u00a0generate\u00a0\u51fd\u6570\u7684\u8c03\u7528\u90fd\u4f1a\u5305\u542b\u72ec\u4e00\u65e0\u4e8c\u7684\u00a0tokenId\u00a0\u503c\u3002\n\n\t\u6240\u6709\u51fd\u6570\u8c03\u7528\u4e2d\uff0ccurrentTime\u00a0\u7684\u503c \u4e25\u683c\u9012\u589e\u00a0\u3002\n\n\t\u6240\u6709\u51fd\u6570\u7684\u8c03\u7528\u6b21\u6570\u603b\u5171\u4e0d\u8d85\u8fc7\u00a02000\u00a0\u6b21\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1a\u3002",
    "\u8f93\u51fa boolean \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass AuthenticationManager:\n    def __init__(self, timeToLive: int):\n        self.ttl = timeToLive\n        self.map = {}\n\n    def generate(self, tokenId: str, currentTime: int) -> None:\n        self.map[tokenId] = currentTime + self.ttl\n\n    def renew(self, tokenId: str, currentTime: int) -> None:\n        if tokenId in self.map and self.map[tokenId] > currentTime:\n            self.map[tokenId] = self.ttl + currentTime\n\n    def countUnexpiredTokens(self, currentTime: int) -> int:\n        res = 0\n        for time in self.map.values():\n            if time > currentTime:\n                res += 1\n        return res\n\ndef main():\n    _lines = [x for x in sys.stdin.read().split('\\n') if x.strip() != '']\n    _ops = json.loads(_lines[0])\n    _args = json.loads(_lines[1]) if len(_lines) > 1 else []\n    _obj = None\n    _out = []\n    for _i, _op in enumerate(_ops):\n        _a = _args[_i] if _i < len(_args) else []\n        if _i == 0:\n            _obj = AuthenticationManager(*_a)\n            _out.append(None)\n        else:\n            _out.append(getattr(_obj, _op)(*_a))\n    print(json.dumps(_out, separators=(',', ':')))\n\nmain()\n",
