    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1ahead\u3001k\u3002",
    "\u8f93\u51fa ListNode[] \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef _list_build(vals):\n    head = cur = ListNode()\n    for v in vals:\n        cur.next = ListNode(v)\n        cur = cur.next\n    return head.next\n\ndef _list_show(head):\n    out = []\n    while head:\n        out.append(head.val)\n        head = head.next\n    return out\n\ndef _list_array_build(arr):\n    return [_list_build(x) for x in arr]\n\ndef _list_array_show(arr):\n    return [_list_show(x) for x in arr]\n\nclass Solution:\n    def splitListToParts(self, head: ListNode, k: int) -> List[ListNode]:\n        n = 0\n        node = head\n        while node:\n            n += 1\n            node = node.next\n        quotient, remainder = n // k, n % k\n\n        parts = [None for _ in range(k)]\n        i, curr = 0, head\n        while i < k and curr:\n            parts[i] = curr\n            part_size = quotient + (1 if i < remainder else 0)\n            for _ in range(part_size - 1):\n                curr = curr.next\n            next = curr.next\n            curr.next = None\n            curr = next\n            i += 1\n        return parts\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n    _args[0] = _list_build(_args[0])\n    _ret = _sol.splitListToParts(_args[0], _args[1])\n    _out = json.dumps([_list_show(x) for x in _ret], separators=(\",\", \":\"))\n    sys.stdout.write(_out)\n\nmain()\n",
